custom_css:
/* === Stranger Things: The Evidence Board 感谢代码楼里老师们的代码https://discord.com/channels/1291925535324110879/1380392618336194702
感谢尾老师，类名，输入框伪提示词来自尾老师，hy老师的去除思维链箭头，na老师的悬浮底栏和思维链文字自定义，楼层信息自定义，12老师的去思维链背景色。感谢NA老师的去阴影，感谢咩野老师的去除全局阴影.=== */
/* --- 1 --- */
@import url('https://fonts.googleapis.com/css2?family=Rock+Salt&family=VT323&family=Caveat:wght@400;700&family=Courier+Prime:ital,wght@0,400;0,700;1,400&display=swap');
@import url("https://fontsapi.zeoseven.com/2102/main/result.css"); /* 中文全局字体: YouchaSanz Light */
@import url("https://fontsapi.zeoseven.com/45/main/result.css");  /* 代码块字体: nzgrRuYinZouZhangKai */
@import url("https://fontsapi.zeoseven.com/2104/main/result.css"); /* 引号包裹字体: RealTypeWriter Light */
@import url("https://fontsapi.zeoseven.com/20/main/result.css");  /* 标题字体: Xiangcui Wave Sans */

/* --- 2. 核心颜色与变量 (黑/红/泛黄复古纸张) --- */
:root {
    --theme-bg-color: #0b0c10; 
    --theme-bg-mid: #1f2833; 
    --card-bg: #ece5d3; /* 泛黄的档案纸/线索板颜色 */
    --accent-red: #E50914; /* 霍金斯警局/Netflix红 */
    --accent-darkred: #8B0000; /* 凝血暗红 */
    --accent-black: #111111; /* 墨迹黑 */
    --text-main: #1a1a1a; /* 纸上的字迹 */
    --text-subtle: #4a4a4a; 

    --font-english-script: 'Caveat', cursive; /* 随性手写体 */
    --font-english-retro: 'Rock Salt', cursive; /* 狂野复古手写 */
    --font-english-typewriter: 'Courier Prime', 'VT323', monospace; /* 打字机/代码 */

    --font-main: "YouchaSanz Light", var(--font-english-script), sans-serif;
    --font-quote: "RealTypeWriter Light", var(--font-english-typewriter), serif;
    --font-code: "nzgrRuYinZouZhangKai", monospace;
    --font-title: "Xiangcui Wave Sans Xiangcui Wave Sans", var(--font-english-retro), sans-serif;
}

/* --- 3. 全局样式：无阴影、无边框、暗黑复古墙纸背景 --- */
* { box-shadow: none !important; border-style: none !important; }
body { 
    background-color: var(--theme-bg-color) !important; 
    background-image: 
        linear-gradient(rgba(11, 12, 16, 0.9), rgba(11, 12, 16, 0.95)),
        repeating-linear-gradient(45deg, #1a1a1a 0, #1a1a1a 2px, transparent 2px, transparent 8px) !important; 
    background-attachment: fixed;
    color: #e0e0e0; /* UI层默认白字 */
    font-family: var(--font-main); 
    font-weight: normal; 
}
#sheld, #character_view { background: transparent !important; margin: 0 auto !important; border: none !important; overflow: visible !important; }
#chat { background: transparent !important; align-items: center !important; padding-bottom: 120px !important; }

/* 霓虹闪烁标题 */
h1, h2, h3, h4, .standoutHeader, .inline-drawer-header, .title_restorable { 
    font-family: var(--font-title); 
    color: var(--accent-red); 
    font-weight: bold; 
    text-transform: uppercase;
    animation: neon-flicker 4s infinite alternate;
}

/* --- 4. 顶部导航栏 & 抽屉背景 --- */
#top-settings-holder { position:relative; background-color: rgba(11, 12, 16, 0.85); backdrop-filter: blur(5px); border-bottom: 2px solid var(--accent-darkred) !important; }

/* 将原生图标修改为80s霓虹红色管状风格 (摒弃原版贴图) */
.drawer-icon.fa-fw { 
    color: var(--accent-red) !important;
    font-size: 22px !important; 
    transition: all 0.3s ease; 
    filter: drop-shadow(0 0 5px var(--accent-red));
}
.drawer-icon.fa-fw:hover { 
    transform: scale(1.2); 
    color: #fff !important;
    filter: drop-shadow(0 0 8px var(--accent-red)) drop-shadow(0 0 15px var(--accent-red));
}
/* 去除之前可能遗留的 background-image */
.drawer-icon { background-image: none !important; }

/* 抽屉与弹窗背景图替换 */
.drawer-content, dialog.popup .popup-body, #dialogue_popup {
    background-image: 
        linear-gradient(rgba(11, 12, 16, 0.85), rgba(11, 12, 16, 0.95)), 
        url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260502/orL0/1200X675/4c84e64d697d0084c282037338ae38e0.jpg/webp') !important;
    background-size: cover; background-position: center;
    border: 1px solid var(--accent-red) !important; 
    border-radius: 0 !important; /* 锋利的边角更符合硬派科幻 */
    color: #e0e0e0 !important;
}

/* --- 5. 底部悬浮输入栏 (对讲机/仪器面板风) --- */
#form_sheld { position: absolute !important; bottom: 15px !important; left: 0; right: 0; display: flex; justify-content: center; z-index: 1000; pointer-events: none; }
#send_form { width: 90% !important; max-width: 800px !important; pointer-events: auto; }

#send_form, body.no-blur #send_form { 
    border-radius: 4px !important; 
    background-color: rgba(15, 15, 18, 0.9) !important; 
    padding: 10px 15px !important; 
    backdrop-filter: blur(8px) !important; 
    border: 1px solid var(--accent-red) !important; 
    transition: all 0.3s ease !important; 
}
#send_form:hover, body.no-blur #send_form:hover { box-shadow: 0 0 15px rgba(229, 9, 20, 0.3) !important; }

#rightSendForm, #leftSendForm { gap: 12px; }
#send_textarea { clip-path: none !important; border: none !important; background: transparent !important; color: #fff !important; font-size: 1.1rem !important; font-family: var(--font-english-typewriter); letter-spacing: 1px; }

#nonQRFormItems { position: relative; }
#send_textarea::placeholder { color: transparent !important; }

/* 伪提示词 (VHS Glitch Effect) */
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before { 
    content: '> Transmitting via Cerebro Walkie-Talkie... 📼_'; 
    color: var(--accent-red); 
    position: absolute; top: 50%; transform: translateY(-50%); left: 50px; right: 70px; 
    font-family: var(--font-english-typewriter); 
    font-size: clamp(1rem, 2.5vw, 1.2rem); 
    pointer-events: none; white-space: nowrap; overflow: hidden;
    opacity: 0.8; 
    animation: vhs-glitch 4s infinite;
}

/* 底栏贴图替换为用户提供的URL */
#options_button::before, #send_but::before, #send_form #extensionsMenuButton::before, #ai_retry_button::before, #auto_completion_button::before, #mes_impersonate::before { display: none !important; }
#options_button, #send_but, #send_form #extensionsMenuButton, #ai_retry_button, #auto_completion_button, #mes_impersonate { 
    width: 38px; height: 38px; 
    background-size: contain; background-repeat: no-repeat; background-position: center; 
    transition: all 0.2s ease; font-size: 0; border: none; background-color: transparent; filter: grayscale(20%);
}
#options_button:hover, #send_but:hover, #send_form #extensionsMenuButton:hover, #ai_retry_button:hover, #auto_completion_button:hover, #mes_impersonate:hover { transform: scale(1.1); filter: grayscale(0) drop-shadow(0 0 5px var(--accent-red)); }

#options_button, #ai_retry_button { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260502/Yup6/1222X1268/2026-05-02%2520155723.png/webp'); }
#send_form #extensionsMenuButton, #auto_completion_button, #mes_impersonate { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260502/Uh2z/1724X1319/2026-05-02%2520155635.png/webp'); }
#send_but { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260502/f9P6/1800X1654/2026-05-02%2520155707.png/webp'); }

/* --- 6. 核心：消息框 (侦探线索板) --- */
.mes { 
    display: flex; flex-direction: column; 
    padding: 0 !important; 
    margin: 60px auto 100px !important; /* 增大上下间距，留出红线空间 */
    width: 90%; max-width: 800px; 
    background-color: transparent !important;
    position: relative;
}

/* --- 消息框顶部背景图 (透明、无边框) --- */
.mes .mesAvatarWrapper {
    display: block; padding: 0;
    width: 100%; 
    height: 350px !important; 
    min-height: 350px !important;
    background-size: cover; background-position: center; background-repeat: no-repeat;
    position: relative; z-index: 5; overflow: visible !important;
    border: none !important; /* 取消边框 */
    background-color: transparent !important; /* 取消背景色 */
    border-radius: 0;
}
/* AI 顶部图片 */
.mes[is_user="false"] .mesAvatarWrapper { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260502/id7U/1200X800/f74c607d687c4ce6103e0e2be3d391f1.jpg/webp'); }
/* 用户 顶部图片 */
.mes[is_user="true"] .mesAvatarWrapper { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260502/jRVc/4578X2298/2026-05-02%2520155842.png/webp'); }

/* 隐秘的胶带固定效果 (贴在图片顶部) */
.mes .mesAvatarWrapper::after {
    content: ''; position: absolute; top: -15px; left: 50%; transform: translateX(-50%) rotate(-2deg);
    width: 100px; height: 30px; background-color: rgba(255, 255, 255, 0.1);
    backdrop-filter: blur(3px); border: 1px solid rgba(255,255,255,0.05);
    box-shadow: 0 2px 5px rgba(0,0,0,0.2);
    z-index: 40;
}

/* --- 7. 正文部分：档案袋与红线连接 --- */
.mes .mes_block { 
    margin-top: 60px !important; /* 拉开距离 */
    background-color: var(--card-bg) !important; /* 泛黄纸张 */
    padding: 35px 40px !important; 
    position: relative; 
    border: 1px solid #c7bca1 !important; 
    min-height: 120px !important; 
    z-index: 10; 
    background-image: none !important; 
    overflow: visible !important; 
    clip-path: none !important; 
    border-radius: 0 !important; /* 实体纸张无圆角 */
}

/* 侦探板红线 (连接顶部大图和下方档案) */
.mes .mes_block::before {
    content: ''; position: absolute;
    top: -65px; height: 65px; width: 3px;
    background: repeating-linear-gradient(to bottom, #d90000, #d90000 5px, #a30000 5px, #a30000 10px);
    z-index: 0;
}
.mes[is_user="false"] .mes_block::before { left: 30%; transform: rotate(-15deg); }
.mes[is_user="true"] .mes_block::before { right: 30%; transform: rotate(15deg); }

/* 档案纸折痕效果 */
.mes .mes_block::after {
    content: ''; position: absolute; top: 0; left: 0; right: 0; bottom: 0;
    background: linear-gradient(135deg, rgba(255,255,255,0.3) 0%, transparent 10%, transparent 90%, rgba(0,0,0,0.05) 100%);
    pointer-events: none; z-index: 1;
}

/* 文本设置，确保在复古纸张上清晰可见 */
.mes .mes_text { line-height: 1.8; color: var(--text-main); font-size: 16.5px; position: relative; z-index: 2; }
/* 引号内文字 */
.mes .mes_text em, .mes .mes_text i { font-family: var(--font-quote); color: var(--accent-darkred); font-style: normal; }

/* --- 8. 头像：硬核机密档案照 (Evidence Photo) --- */
.mes .avatar {
    position: absolute;
    top: 50%; 
    width: 140px !important; height: 180px !important; 
    background: #e8e6e1 !important; /* 老旧相纸底色 */
    padding: 6px !important; /* 均匀的窄白边，还原冲洗照片 */
    z-index: 30; display: flex !important; align-items: flex-start; justify-content: center;
    border: 1px solid #999 !important; /* 锐利的照片切边 */
    border-radius: 0 !important; /* 拒绝圆角，展现档案严肃感 */
    /* 档案黑白列印滤镜：去色、高对比、轻微泛黄、加阴影 */
    filter: grayscale(85%) contrast(1.2) sepia(0.2) drop-shadow(3px 5px 8px rgba(0,0,0,0.6)); 
}
/* 左右头像微弱的角度偏差 */
.mes[is_user="false"] .avatar { left: 20px; transform: translateY(-50%) rotate(-3deg); }
.mes[is_user="true"] .avatar { right: 20px; left: auto; transform: translateY(-50%) rotate(4deg); }

.mes .avatar img { 
    width: 100% !important; height: 100% !important; 
    object-fit: cover !important; 
}

/* 金属回形针固定效果 (夹在照片角上) - SVG 替换版 */
.mes .avatar::before {
    content: ''; /* 清空了原来的 Emoji */
    position: absolute;
    top: -15px; 
    width: 28px;  /* 回形针的宽度 */
    height: 28px; /* 回形针的高度 */
    /* 纯手写内联 SVG 代码，颜色为复古深银灰色，线条加粗 */
    background-image: url("data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%23888888' stroke-width='2.5' stroke-linecap='round' stroke-linejoin='round'%3E%3Cpath d='M21.44 11.05l-9.19 9.19a6 6 0 0 1-8.49-8.49l9.19-9.19a4 4 0 0 1 5.66 5.66l-9.2 9.19a2 2 0 0 1-2.83-2.83l8.49-8.48'/%3E%3C/svg%3E");
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    z-index: 40;
    /* 增加更逼真的物理阴影，使其更像夹在纸上的立体物件 */
    filter: drop-shadow(2px 3px 2px rgba(0,0,0,0.6));
}

/* 左右两边不同的倾斜角度保持不变 */
.mes[is_user="false"] .avatar::before { left: 10px; transform: rotate(15deg); }
.mes[is_user="true"] .avatar::before { right: 10px; transform: rotate(-15deg) scaleX(-1); }


/* 盖在照片上的红色油墨机密印章 */
.mes .avatar::after {
    content: 'CLASSIFIED'; white-space: nowrap; position: absolute;
    bottom: 15px; left: 50%; transform: translateX(-50%) rotate(-12deg);
    font-family: var(--font-english-typewriter); font-size: 18px; color: #cc0000;
    font-weight: bold; border: 2px solid #cc0000; padding: 2px 6px;
    border-radius: 2px; opacity: 0.85; 
    mix-blend-mode: multiply; /* 模拟真实印章墨水透底效果 */
    text-align: center; background: transparent; letter-spacing: 2px;
}

/* --- 楼层与时间戳 (机密印章风) --- */
.mes .mesIDDisplay, .mes .mes_timer {
    position: absolute !important; 
    background-color: transparent !important; 
    color: var(--accent-darkred) !important; 
    font-size: 14px !important; 
    font-family: var(--font-english-typewriter) !important; 
    font-weight: bold;
    letter-spacing: 1px !important; z-index: 40 !important;
    border: 2px solid var(--accent-darkred) !important;
    padding: 2px 8px !important;
    border-radius: 0 !important;
    opacity: 0.8;
}
.mes .mesIDDisplay { top: -40px !important; left: 10px !important; transform: rotate(-5deg) !important; }
.mes .mes_timer { bottom: -20px !important; right: 10px !important; transform: rotate(3deg) !important; top: auto !important; }
.mesIDDisplay::before { content: 'EVIDENCE FILE #'; }
.mesIDDisplay::after { content: ' █'; }

/* --- 英文装饰性文字 (背景隐藏信息) --- */
.mes_block .mes_text::after {
    content: 'HAWKINS NATIONAL LABORATORY \A DEPARTMENT OF ENERGY \A CLASSIFIED'; 
    white-space: pre; position: absolute; top: 30%; color: rgba(139, 0, 0, 0.05);
    font-family: var(--font-english-typewriter); font-size: 28px; text-align: center; 
    font-weight: bold; transform: rotate(-30deg); z-index: -1; pointer-events: none; user-select: none;
}
.mes[is_user="false"] .mes_block .mes_text::after { right: 10%; }
.mes[is_user="true"] .mes_block .mes_text::after { left: 10%; }

/* --- 思维链自定义 (无线电解密) --- */
#chat .mes .mes_reasoning_header { background: transparent !important; border: none !important; border-radius: 0; padding: 0 !important; margin-bottom: 15px !important; display: inline-flex !important; align-items: center !important; }
.mes_reasoning_arrow { display: none !important; }
.mes_reasoning_header h4, .mes_reasoning_header_title { font-size: 0 !important; visibility: hidden; }
.mes_reasoning_header h4::before, .mes_reasoning_header_title::before { 
    content: "📻 Decrypting Upside Down signals... "; 
    font-family: var(--font-english-typewriter); font-size: 16px !important; 
    color: var(--accent-darkred); visibility: visible; letter-spacing: 1px; 
    animation: crt-flicker 2s infinite;
}
.mes_reasoning { 
    padding: 10px 15px !important; margin-bottom: 20px !important; 
    color: var(--text-subtle); font-family: var(--font-english-typewriter); font-size: 14px; 
    background-color: rgba(0,0,0,0.03);
    border-left: 4px solid var(--accent-darkred);
}

/* --- 打字指示器 (霓虹卡带) --- */
#typing_indicator { 
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260502/Uh2z/1724X1319/2026-05-02%2520155635.png/webp') !important; 
    background-size: contain !important; background-repeat: no-repeat !important; background-position: center !important; 
    animation: float-flicker 1.5s infinite alternate; border: none !important; 
    height: 40px !important; width: 40px !important; margin: 15px auto !important; 
    filter: invert(1) hue-rotate(180deg);
}
#typing_indicator .dot { display: none !important; }

/* --- 悬浮按钮 (黑色印章风) --- */
.mes .mes_buttons, .mes .mes_edit_buttons { flex-direction: row-reverse; gap: 8px; opacity: 0; transition: opacity 0.4s ease; pointer-events: auto !important; margin-top: 15px; position: relative; z-index: 15; }
.mes:hover .mes_buttons, .mes:hover .mes_edit_buttons { opacity: 1; }
.mes .mes_buttons .mes_button, .mes .mes_edit_buttons .mes_button { 
    background-color: var(--accent-black) !important; color: #fff !important; 
    padding: 6px !important; border-radius: 0 !important; cursor: pointer; transition: all 0.2s ease; font-size: 14px !important; border: 1px solid var(--accent-red) !important; 
}
.mes .mes_buttons .mes_button:hover, .mes .mes_edit_buttons .mes_button:hover { background-color: var(--accent-red) !important; color: #fff !important; transform: scale(1.1); }

/* --- 全局UI设定 (硬核终端风) --- */
.standoutHeader, .inline-drawer-header, .title_restorable, #extensions_settings2 > div, #extensions_settings > div, .openai_logit_bias_preset_form, details > summary, #power-user-options-block h4, #InstructSettingsColumn h4, #SystemPromptColumn h4, #ContextSettings h4, .persona_management_global_settings h4, #character_popup h4, #AdvancedFormatting h4, #rm_group_chats_block h4, div[name*='HandlingToggles'] h4, div[name*='MiscellaneousToggles'] h4 { 
    background: rgba(20, 20, 20, 0.8) !important; border-radius: 0 !important; padding: 12px 18px !important; margin-bottom: 10px !important; color: #fff !important; border-left: 3px solid var(--accent-red) !important; font-family: var(--font-english-typewriter);
}
input[type="text"], input[type="number"], input[type="search"], textarea, select, .text_pole { background-color: #111 !important; color: var(--accent-red) !important; border-radius: 0 !important; padding: 10px !important; border: 1px solid #333 !important; font-family: var(--font-english-typewriter); }
input:focus, textarea:focus, select:focus { outline: none !important; border-color: var(--accent-red) !important; box-shadow: 0 0 8px rgba(229, 9, 20, 0.5) !important; }
.menu_button { background-color: #1a1a1a !important; color: #aaa !important; transition: all 0.3s ease; border-radius: 0 !important; border: 1px solid #333 !important; }
.menu_button:hover, .menu_button.active, .menu_button.world_set, .menu_button.fav_on, #left-nav-panel .menu_button.selected { background-color: var(--accent-red) !important; color: white !important; border-color: var(--accent-red) !important; }
input[type="checkbox"]:checked::before { box-shadow: inset 1em 1em var(--accent-red) !important; }

/* 弹窗按钮 */
#dialogue_del_mes_ok, #dialogue_del_mes_cancel { background-color: #111 !important; color: #fff !important; border-radius: 0 !important; padding: 12px 24px !important; margin: 10px 8px !important; transition: all 0.3s ease !important; border: 1px solid var(--accent-red) !important; font-family: var(--font-english-typewriter);}
#dialogue_del_mes_ok:hover { background-color: var(--accent-red) !important; color: #fff !important; }
#dialogue_del_mes_cancel:hover { background-color: #333 !important; color: #fff !important; }

/* ========================================================
   电脑端微调
======================================================== */
@media (min-width: 800px) {
    .mes[is_user="false"] .avatar { left: 80px !important; }
    .mes[is_user="true"] .avatar { right: 80px !important; }
}

/* --- 手机端适配调整 --- */
@media (max-width: 768px) {
    .mes { margin: 80px auto 60px !important; }
    .mes .mesAvatarWrapper { height: 220px !important; min-height: 220px !important; }
    .mes .mes_block { margin-top: 40px !important; padding: 25px 20px !important; }
    .mes > .ch_name, .mes .mes_block > .ch_name { top: -15px !important; padding: 3px 10px !important; }
    .mes[is_user="false"] > .ch_name, .mes[is_user="false"] .mes_block > .ch_name { left: 5px !important; }
    .mes[is_user="true"] > .ch_name, .mes[is_user="true"] .mes_block > .ch_name { right: 5px !important; }
    .mes .ch_name .name_text { font-size: 14px !important; }
    .mes .avatar { width: 100px !important; height: 120px !important; padding: 5px 5px 25px 5px !important; }
    .mes .avatar::after { font-size: 10px; bottom: 5px; }
    .mes .mesIDDisplay { left: 5px !important; top: -30px !important; font-size: 11px !important; }
    .mes .mes_timer { right: 5px !important; bottom: -15px !important; font-size: 11px !important; }
}

/* --- 动画关键帧 --- */
@keyframes neon-flicker {
  0%, 19%, 21%, 23%, 25%, 54%, 56%, 100% {
    text-shadow:
      -0.2rem -0.2rem 1rem #fff,
      0.2rem 0.2rem 1rem #fff,
      0 0 2rem var(--accent-red),
      0 0 4rem var(--accent-red),
      0 0 6rem var(--accent-red),
      0 0 8rem var(--accent-red),
      0 0 10rem var(--accent-red);
    opacity: 1;
  }
  20%, 24%, 55% { text-shadow: none; opacity: 0.4; }
}

@keyframes vhs-glitch {
    0% { transform: translateY(-50%) skewX(0deg); opacity: 0.8; }
    10% { transform: translateY(-50%) skewX(-15deg); opacity: 0.5; color: #fff; }
    11% { transform: translateY(-50%) skewX(0deg); opacity: 0.8; color: var(--accent-red); }
    50% { transform: translateY(-50%) skewX(0deg); opacity: 0.8; }
    51% { transform: translateY(-50%) skewX(10deg); opacity: 0.6; }
    52% { transform: translateY(-50%) skewX(0deg); opacity: 0.8; }
    100% { transform: translateY(-50%) skewX(0deg); opacity: 0.8; }
}

@keyframes crt-flicker {
    0% { opacity: 1; }
    50% { opacity: 0.6; }
    100% { opacity: 1; }
}

@keyframes float-flicker {
    0% { transform: translateY(0); opacity: 0.8; filter: invert(1) hue-rotate(180deg) drop-shadow(0 0 5px red); }
    100% { transform: translateY(-5px); opacity: 1; filter: invert(1) hue-rotate(180deg) drop-shadow(0 0 15px red); }
}

/* --- 微调：用户头像向左移动 --- */
/* 手机/平板等默认状态下，增大 right 的值使其向左移 */
.mes[is_user="true"] .avatar { 
    right: 80px !important; 
}

/* 电脑端大屏幕下，同步增大 right 的值 */
@media (min-width: 800px) {
    .mes[is_user="true"] .avatar { 
        right: 200px !important;
    }
}

/* --- 微调：输入框伪提示词向右移动 --- */
/* 增加 left 的间距，避开左侧的附加/菜单按钮 */
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before { 
    left: 75px !important; 
}
/* --- 名字：红色Dymo立体压花胶带 (拼贴版) --- */
.mes > .ch_name, .mes .mes_block > .ch_name { 
    display: flex !important; 
    position: absolute !important; 
    top: -15px !important; /* 微调位置，让贴合感更强 */
    bottom: auto !important;
    background: #cc0000 !important; /* Dymo胶带的经典红色 */
    border: none !important; /* 胶带不需要边框 */
    border-radius: 2px !important; /* 塑料材质的轻微圆角 */
    padding: 4px 15px !important; 
    z-index: 40 !important; 
    align-items: center !important; 
    /* 核心效果：融合了[立体凹凸感]和[悬浮投影]，增强拼贴感 */
    box-shadow: 
        inset -1px -2px 0 rgba(0,0,0,0.5), 
        inset 1px 1px 0 rgba(255,255,255,0.3),
        2px 4px 6px rgba(0,0,0,0.4) !important;
}

/* AI 名字：贴在左侧，保持歪斜 */
.mes[is_user="false"] > .ch_name, .mes[is_user="false"] .mes_block > .ch_name { 
    left: 15px !important; 
    right: auto !important; 
    transform: rotate(-4deg) !important; /* 保留拼贴的随性角度 */
}

/* 用户名字：贴在右侧，保持歪斜 */
.mes[is_user="true"] > .ch_name, .mes[is_user="true"] .mes_block > .ch_name { 
    right: 15px !important; 
    left: auto !important; 
    transform: rotate(3deg) !important; /* 保留拼贴的随性角度 */
}

/* 名字字体：还原为Dymo打字机立体浮雕效果 */
.mes .ch_name .name_text { 
    font-family: var(--font-english-typewriter), monospace !important; 
    font-size: 18px !important; 
    letter-spacing: 2px !important; 
    color: #fff !important; /* 浮雕文字是白色的 */
    text-transform: uppercase !important; 
    /* 模拟文字被压进去的阴影效果 */
    text-shadow: 1px 1px 0 rgba(0,0,0,0.8) !important; 
    font-weight: normal !important; /* 字体本身已经够粗，无需额外加粗 */
}
